def feature(history):
    col = "smart_191_raw"
    def _member(g):
        return bool(g[col].notna().any())

    def _raw(g):
        if not _member(g):
            return np.nan
        g = g.sort_values("date")
        v = g[col].astype(float).iloc[-1]
        if not pd.notna(v):
            return np.nan
        return float(np.log1p(max(float(v), 0.0)))

    raw = history.groupby("serial_number", group_keys=False).apply(_raw)
    med = float(raw.dropna().median()) if raw.notna().any() else 0.0
    members = history.groupby("serial_number", group_keys=False).apply(_member)
    out = pd.Series(index=members.index.astype(str), dtype=float)
    for sn, is_mem in members.items():
        key = str(sn)
        if is_mem:
            v = raw.loc[sn]
            out[key] = float(v - med) if pd.notna(v) else np.nan
        else:
            out[key] = 0.0
    return out

