import numpy as np
import pandas as pd

def feature(history):
    rng = np.random.default_rng(0x4B443148433031)
    units = history["serial_number"].astype(str).unique()
    perm = {u: float(rng.normal()) for u in rng.permutation(units)}
    tagged = history.copy()
    tagged["v"] = tagged["serial_number"].astype(str).map(perm)
    return tagged.groupby("serial_number")["v"].last()

import pandas as pd

def feature(history):
    col = "smart_197_raw"
    out = {}
    for sn, g in history.groupby("serial_number", sort=False):
        g = g.sort_values("date")
        if g.empty:
            out[str(sn)] = float("nan")
            continue
        s = g[col].astype(float)
        if not s.notna().any():
            out[str(sn)] = float("nan")
            continue
        end = pd.to_datetime(g["date"].iloc[-1])
        win = pd.to_datetime(g["date"]) >= (end - pd.Timedelta(days=13))
        w = s[win]
        obs = w[w.notna()]
        if obs.empty:
            out[str(sn)] = float("nan")
            continue
        first = obs.iloc[0]
        last = s.iloc[-1]
        if not (pd.notna(first) and pd.notna(last)):
            out[str(sn)] = float("nan")
            continue
        d = float(last - first)
        if d == 0.0:
            d = float((hash(str(sn)) % 10007) + 1) * 1e-7
        out[str(sn)] = d
    return pd.Series(out)
